import{_ as a,o as t,c as r,a3 as o}from"./chunks/framework.rQcsxYkC.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"reference/faq.md","filePath":"reference/faq.md","lastUpdated":1785888355000}'),n={name:"reference/faq.md"};function i(s,e,d,h,c,l){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="what-is-a-arc-name" tabindex="-1">What is a .arc name? <a class="header-anchor" href="#what-is-a-arc-name" aria-label="Permalink to &quot;What is a .arc name?&quot;">​</a></h3><p>A human-readable identifier on the Arc network that maps to an address, a profile and other records. <code>alice.arc</code> instead of <code>0x3dC38247c4f9672B2C98aCfdc5C1302f8d897E9C</code>. See <a href="/docs/guide/what-is-arc-names.html">What is Arc Names</a>.</p><h3 id="will-it-work-in-a-browser-address-bar" tabindex="-1">Will it work in a browser address bar? <a class="header-anchor" href="#will-it-work-in-a-browser-address-bar" aria-label="Permalink to &quot;Will it work in a browser address bar?&quot;">​</a></h3><p>No. A <code>.arc</code> name is an on-chain identifier resolved by wallets and apps that support it, not a DNS domain.</p><h3 id="is-this-the-same-as-ens" tabindex="-1">Is this the same as ENS? <a class="header-anchor" href="#is-this-the-same-as-ens" aria-label="Permalink to &quot;Is this the same as ENS?&quot;">​</a></h3><p>Not the same deployment, but the same architecture — registry → resolver, the same namehash algorithm, the same reverse-record convention. If you&#39;ve integrated ENS, resolution here will look familiar.</p><h3 id="do-i-get-a-mainnet-name-for-registering-on-testnet" tabindex="-1">Do I get a mainnet name for registering on testnet? <a class="header-anchor" href="#do-i-get-a-mainnet-name-for-registering-on-testnet" aria-label="Permalink to &quot;Do I get a mainnet name for registering on testnet?&quot;">​</a></h3><p>No. Nothing about a testnet registration reserves or grants a mainnet name. Anyone telling you otherwise is making it up. See <a href="/docs/safety.html#testnet-reality-check">Safety</a>.</p><h3 id="is-there-a-token" tabindex="-1">Is there a token? <a class="header-anchor" href="#is-there-a-token" aria-label="Permalink to &quot;Is there a token?&quot;">​</a></h3><p>No. There is no Arc Names token, no airdrop, and no points programme. Treat any claim otherwise as a scam.</p><h2 id="registering" tabindex="-1">Registering <a class="header-anchor" href="#registering" aria-label="Permalink to &quot;Registering&quot;">​</a></h2><h3 id="why-does-registration-take-two-transactions" tabindex="-1">Why does registration take two transactions? <a class="header-anchor" href="#why-does-registration-take-two-transactions" aria-label="Permalink to &quot;Why does registration take two transactions?&quot;">​</a></h3><p>To stop front-running. A single transaction would broadcast the name you want into a public mempool where anyone could outbid your gas and take it. The commitment goes first and reveals nothing. See <a href="/docs/guide/registering.html#why-two-transactions">Registering a name</a>.</p><h3 id="how-long-do-i-wait-between-them" tabindex="-1">How long do I wait between them? <a class="header-anchor" href="#how-long-do-i-wait-between-them" aria-label="Permalink to &quot;How long do I wait between them?&quot;">​</a></h3><p>As long as the contract&#39;s <code>minCommitAge</code>, which the owner can change. The app shows a live countdown. There&#39;s also a maximum — wait too long and the commitment expires and you start over.</p><h3 id="what-happens-if-i-close-the-tab-mid-registration" tabindex="-1">What happens if I close the tab mid-registration? <a class="header-anchor" href="#what-happens-if-i-close-the-tab-mid-registration" aria-label="Permalink to &quot;What happens if I close the tab mid-registration?&quot;">​</a></h3><p>The secret lives in your browser under <code>arc:pending-commitments:v2</code>. If it survives, you can finish. If you cleared site data or switched browsers, the commitment is unusable — you lose the commit gas and start again. The name isn&#39;t reserved for you meanwhile.</p><h3 id="what-characters-can-a-name-contain" tabindex="-1">What characters can a name contain? <a class="header-anchor" href="#what-characters-can-a-name-contain" aria-label="Permalink to &quot;What characters can a name contain?&quot;">​</a></h3><p>The app allows lowercase letters, digits and hyphens, no leading or trailing hyphen, up to 63 characters. The <strong>contract</strong> is looser — it only enforces length and rejects uppercase ASCII. So names in the wild may contain characters the app would never let you type. See <a href="/docs/safety.html#look-alike-names">Safety → look-alike names</a>.</p><h3 id="can-i-register-several-names-at-once" tabindex="-1">Can I register several names at once? <a class="header-anchor" href="#can-i-register-several-names-at-once" aria-label="Permalink to &quot;Can I register several names at once?&quot;">​</a></h3><p>Yes — <code>registerMany</code> handles 1 to 20 names under one commitment. One invalid or unavailable name reverts the whole batch.</p><h3 id="can-i-register-a-two-character-name" tabindex="-1">Can I register a two-character name? <a class="header-anchor" href="#can-i-register-a-two-character-name" aria-label="Permalink to &quot;Can I register a two-character name?&quot;">​</a></h3><p>Only if the contract&#39;s 2-character price is non-zero. When it&#39;s zero the entire tier is disabled and such names fail validation. See <a href="/docs/guide/pricing.html#two-character-names-can-be-switched-off">Pricing</a>.</p><h3 id="does-my-name-resolve-immediately-after-registering" tabindex="-1">Does my name resolve immediately after registering? <a class="header-anchor" href="#does-my-name-resolve-immediately-after-registering" aria-label="Permalink to &quot;Does my name resolve immediately after registering?&quot;">​</a></h3><p>Yes. The controller binds a resolver and sets the address record to you in the same transaction. What is <em>not</em> automatic is the reverse record — see <a href="/docs/guide/primary-name.html">Your primary name</a>.</p><h2 id="pricing" tabindex="-1">Pricing <a class="header-anchor" href="#pricing" aria-label="Permalink to &quot;Pricing&quot;">​</a></h2><h3 id="how-much-does-a-name-cost" tabindex="-1">How much does a name cost? <a class="header-anchor" href="#how-much-does-a-name-cost" aria-label="Permalink to &quot;How much does a name cost?&quot;">​</a></h3><p>It depends on length — there are four tiers (2, 3, 4, 5+ characters), each an owner-configurable per-year rate. The app shows the live price before you confirm. These docs deliberately don&#39;t print numbers that would go stale. See <a href="/docs/guide/pricing.html">Pricing &amp; rarity</a>.</p><h3 id="is-a-shorter-name-always-more-expensive" tabindex="-1">Is a shorter name always more expensive? <a class="header-anchor" href="#is-a-shorter-name-always-more-expensive" aria-label="Permalink to &quot;Is a shorter name always more expensive?&quot;">​</a></h3><p>Not necessarily. The tiers are independent values, not a curve — the owner sets each separately. Read the actual rate rather than inferring it from length.</p><h3 id="what-if-i-send-too-much" tabindex="-1">What if I send too much? <a class="header-anchor" href="#what-if-i-send-too-much" aria-label="Permalink to &quot;What if I send too much?&quot;">​</a></h3><p>The contract refunds the difference in the same transaction. The app deliberately quotes a small buffer so a price change doesn&#39;t fail your transaction; you&#39;re never charged it.</p><h3 id="why-is-the-price-in-usdc-with-18-decimals" tabindex="-1">Why is the price in USDC with 18 decimals? <a class="header-anchor" href="#why-is-the-price-in-usdc-with-18-decimals" aria-label="Permalink to &quot;Why is the price in USDC with 18 decimals?&quot;">​</a></h3><p>Arc&#39;s native gas token is USDC, and as a native token it uses 18 decimals rather than the 6 of the ERC-20. Pricing is scaled so 1 USD = 1e18 wei, which means <code>price()</code> returns the USD figure directly. See <a href="/docs/protocol/fees.html#two-kinds-of-usdc">Fees</a>.</p><h2 id="renewals-and-expiry" tabindex="-1">Renewals and expiry <a class="header-anchor" href="#renewals-and-expiry" aria-label="Permalink to &quot;Renewals and expiry&quot;">​</a></h2><h3 id="what-happens-when-my-name-expires" tabindex="-1">What happens when my name expires? <a class="header-anchor" href="#what-happens-when-my-name-expires" aria-label="Permalink to &quot;What happens when my name expires?&quot;">​</a></h3><p>It stops working immediately — <code>ownerOf</code> reverts and apps stop resolving it. But it stays locked to you for <strong>90 days</strong>, during which you can renew and restore it. After that, anyone can register it. See <a href="/docs/guide/renewals.html">Renewals &amp; expiry</a>.</p><h3 id="can-someone-take-my-name-the-moment-it-expires" tabindex="-1">Can someone take my name the moment it expires? <a class="header-anchor" href="#can-someone-take-my-name-the-moment-it-expires" aria-label="Permalink to &quot;Can someone take my name the moment it expires?&quot;">​</a></h3><p>No. The 90-day grace period blocks everyone else. Registration attempts revert with <code>taken</code>.</p><h3 id="can-someone-else-renew-my-name-for-me" tabindex="-1">Can someone else renew my name for me? <a class="header-anchor" href="#can-someone-else-renew-my-name-for-me" aria-label="Permalink to &quot;Can someone else renew my name for me?&quot;">​</a></h3><p>Yes, and it&#39;s safe — renewal only extends the expiry, never changes ownership or records. This is useful: a name in cold storage can be renewed from a hot wallet without exposing the hardware key.</p><h3 id="does-renewing-early-waste-the-time-i-have-left" tabindex="-1">Does renewing early waste the time I have left? <a class="header-anchor" href="#does-renewing-early-waste-the-time-i-have-left" aria-label="Permalink to &quot;Does renewing early waste the time I have left?&quot;">​</a></h3><p>No. The new expiry is the old expiry plus your duration. It stacks.</p><h3 id="is-there-an-auction-when-a-name-is-released" tabindex="-1">Is there an auction when a name is released? <a class="header-anchor" href="#is-there-an-auction-when-a-name-is-released" aria-label="Permalink to &quot;Is there an auction when a name is released?&quot;">​</a></h3><p>No. No premium decay, no auction, no priority for the previous owner. The price drops to the normal tier rate immediately and the first valid commit-reveal wins.</p><h2 id="records-and-profile" tabindex="-1">Records and profile <a class="header-anchor" href="#records-and-profile" aria-label="Permalink to &quot;Records and profile&quot;">​</a></h2><h3 id="why-can-t-i-edit-my-records" tabindex="-1">Why can&#39;t I edit my records? <a class="header-anchor" href="#why-can-t-i-edit-my-records" aria-label="Permalink to &quot;Why can&#39;t I edit my records?&quot;">​</a></h3><p>Most likely you received the name by transfer and haven&#39;t reclaimed it. Resolver writes are authorised against <strong>registry</strong> ownership, not token ownership. Call <code>registrar.reclaim(tokenId, you)</code> first. See <a href="/docs/guide/ownership.html#reclaiming-after-a-transfer">Ownership</a>.</p><h3 id="why-does-each-record-cost-a-separate-transaction" tabindex="-1">Why does each record cost a separate transaction? <a class="header-anchor" href="#why-does-each-record-cost-a-separate-transaction" aria-label="Permalink to &quot;Why does each record cost a separate transaction?&quot;">​</a></h3><p>Each write is a separate contract call. Changing your avatar and website is two transactions.</p><h3 id="are-my-records-private" tabindex="-1">Are my records private? <a class="header-anchor" href="#are-my-records-private" aria-label="Permalink to &quot;Are my records private?&quot;">​</a></h3><p>No. Everything is plaintext on a public chain, readable by anyone, permanently — overwriting doesn&#39;t erase history. An <code>email</code> record will be scraped.</p><h3 id="is-a-social-handle-in-a-record-verified" tabindex="-1">Is a social handle in a record verified? <a class="header-anchor" href="#is-a-social-handle-in-a-record-verified" aria-label="Permalink to &quot;Is a social handle in a record verified?&quot;">​</a></h3><p>No. The resolver stores whatever the owner writes. A <code>com.twitter</code> record is a self-reported claim the protocol never checks.</p><h2 id="primary-names" tabindex="-1">Primary names <a class="header-anchor" href="#primary-names" aria-label="Permalink to &quot;Primary names&quot;">​</a></h2><h3 id="why-doesn-t-my-name-show-up-in-other-apps" tabindex="-1">Why doesn&#39;t my name show up in other apps? <a class="header-anchor" href="#why-doesn-t-my-name-show-up-in-other-apps" aria-label="Permalink to &quot;Why doesn&#39;t my name show up in other apps?&quot;">​</a></h3><p>Registering sets the forward record (name → address). Displaying your name requires the <strong>reverse</strong> record (address → name), which you set separately. See <a href="/docs/guide/primary-name.html">Your primary name</a>.</p><h3 id="why-did-my-primary-name-stop-displaying" tabindex="-1">Why did my primary name stop displaying? <a class="header-anchor" href="#why-did-my-primary-name-stop-displaying" aria-label="Permalink to &quot;Why did my primary name stop displaying?&quot;">​</a></h3><p>The round-trip verification broke — usually because the name&#39;s address record changed, the name was transferred away, or it expired. Apps fall back to your address. Nothing is at risk.</p><h3 id="can-two-wallets-share-a-primary-name" tabindex="-1">Can two wallets share a primary name? <a class="header-anchor" href="#can-two-wallets-share-a-primary-name" aria-label="Permalink to &quot;Can two wallets share a primary name?&quot;">​</a></h3><p>Not really. The reverse record lives on the address, and the name&#39;s <code>addr</code> holds a single address, so only one wallet can round-trip successfully.</p><h2 id="ownership-and-transfers" tabindex="-1">Ownership and transfers <a class="header-anchor" href="#ownership-and-transfers" aria-label="Permalink to &quot;Ownership and transfers&quot;">​</a></h2><h3 id="is-a-arc-name-an-nft" tabindex="-1">Is a .arc name an NFT? <a class="header-anchor" href="#is-a-arc-name-an-nft" aria-label="Permalink to &quot;Is a .arc name an NFT?&quot;">​</a></h3><p>Yes, ERC-721. The token ID is <code>uint256(keccak256(bytes(label)))</code>.</p><h3 id="i-transferred-a-name-and-the-recipient-can-t-edit-records" tabindex="-1">I transferred a name and the recipient can&#39;t edit records. <a class="header-anchor" href="#i-transferred-a-name-and-the-recipient-can-t-edit-records" aria-label="Permalink to &quot;I transferred a name and the recipient can&#39;t edit records.&quot;">​</a></h3><p>Expected. They need to call <code>reclaim</code>. Until then you remain the registry owner and can still change the records.</p><h3 id="i-bought-a-name-and-it-still-resolves-to-the-seller" tabindex="-1">I bought a name and it still resolves to the seller. <a class="header-anchor" href="#i-bought-a-name-and-it-still-resolves-to-the-seller" aria-label="Permalink to &quot;I bought a name and it still resolves to the seller.&quot;">​</a></h3><p>Also expected. The address record isn&#39;t cleared on transfer — the new owner must call <code>setAddr</code>. Anyone paying the name before then pays the seller. Do this immediately.</p><h3 id="can-i-transfer-a-name-in-its-grace-period" tabindex="-1">Can I transfer a name in its grace period? <a class="header-anchor" href="#can-i-transfer-a-name-in-its-grace-period" aria-label="Permalink to &quot;Can I transfer a name in its grace period?&quot;">​</a></h3><p>No. Every operation that calls <code>ownerOf</code> reverts once past expiry. <a href="/docs/guide/renewals.html">Renew it first</a>.</p><h3 id="can-i-get-a-name-back-after-sending-it-to-the-wrong-address" tabindex="-1">Can I get a name back after sending it to the wrong address? <a class="header-anchor" href="#can-i-get-a-name-back-after-sending-it-to-the-wrong-address" aria-label="Permalink to &quot;Can I get a name back after sending it to the wrong address?&quot;">​</a></h3><p>No. Transfers are irreversible and there is no admin who can undo one.</p><h2 id="marketplace" tabindex="-1">Marketplace <a class="header-anchor" href="#marketplace" aria-label="Permalink to &quot;Marketplace&quot;">​</a></h2><h3 id="does-the-marketplace-hold-my-name" tabindex="-1">Does the marketplace hold my name? <a class="header-anchor" href="#does-the-marketplace-hold-my-name" aria-label="Permalink to &quot;Does the marketplace hold my name?&quot;">​</a></h3><p>No. It&#39;s escrow-free — the name stays in your wallet and the market holds only an approval, which it uses to transfer at the moment of sale.</p><h3 id="what-fee-does-the-marketplace-take" tabindex="-1">What fee does the marketplace take? <a class="header-anchor" href="#what-fee-does-the-marketplace-take" aria-label="Permalink to &quot;What fee does the marketplace take?&quot;">​</a></h3><p><code>feeBps</code>, deducted from the seller&#39;s proceeds. It initialises to <strong>zero</strong>, so unless the owner has changed it the seller gets the full price. Read <code>feeBps()</code> for the live value.</p><h3 id="can-a-seller-raise-the-price-as-i-buy" tabindex="-1">Can a seller raise the price as I buy? <a class="header-anchor" href="#can-a-seller-raise-the-price-as-i-buy" aria-label="Permalink to &quot;Can a seller raise the price as I buy?&quot;">​</a></h3><p>Only if you let them. Use <code>buy(id, maxPrice)</code> with an explicit maximum and the transaction reverts with <code>price moved</code> instead. The one-argument <code>buy(id)</code> sets the maximum to whatever you sent — don&#39;t use it. See <a href="/docs/guide/marketplace.html#maxprice-protects-you">Marketplace</a>.</p><h3 id="can-i-buy-a-name-that-isn-t-listed" tabindex="-1">Can I buy a name that isn&#39;t listed? <a class="header-anchor" href="#can-i-buy-a-name-that-isn-t-listed" aria-label="Permalink to &quot;Can I buy a name that isn&#39;t listed?&quot;">​</a></h3><p>Not through the marketplace. Contact the owner — the app and the API both show their address, and many owners set contact records. Never pay outside an atomic transaction. See <a href="/docs/safety.html#buying-a-name-safely">Safety</a>.</p><h3 id="why-can-t-i-buy-this-listing" tabindex="-1">Why can&#39;t I buy this listing? <a class="header-anchor" href="#why-can-t-i-buy-this-listing" aria-label="Permalink to &quot;Why can&#39;t I buy this listing?&quot;">​</a></h3><p>If it reverts with <code>usdc listing</code>, it settles in ERC-20 USDC and the app only handles native. Filter for <code>currency: 0</code> in API results.</p><h2 id="integrating" tabindex="-1">Integrating <a class="header-anchor" href="#integrating" aria-label="Permalink to &quot;Integrating&quot;">​</a></h2><h3 id="how-do-i-resolve-a-name-in-my-app" tabindex="-1">How do I resolve a name in my app? <a class="header-anchor" href="#how-do-i-resolve-a-name-in-my-app" aria-label="Permalink to &quot;How do I resolve a name in my app?&quot;">​</a></h3><p>Two calls: <code>registry.resolver(node)</code> then <code>resolver.addr(node)</code>. Full code in <a href="/docs/protocol/resolving.html#forward-resolution">Resolving .arc</a>.</p><h3 id="how-do-i-display-someone-s-name" tabindex="-1">How do I display someone&#39;s name? <a class="header-anchor" href="#how-do-i-display-someone-s-name" aria-label="Permalink to &quot;How do I display someone&#39;s name?&quot;">​</a></h3><p><code>universalResolver.reverse(address)</code>, and <strong>only</strong> display the result when the <code>verified</code> flag is true. Otherwise show the address.</p><h3 id="should-i-read-the-contracts-or-the-api" tabindex="-1">Should I read the contracts or the API? <a class="header-anchor" href="#should-i-read-the-contracts-or-the-api" aria-label="Permalink to &quot;Should I read the contracts or the API?&quot;">​</a></h3><p>The API for display and history — portfolios, activity feeds, listings. The contracts for anything that moves value. The indexer lags the chain and can fail; check <code>GET /api/v1/sync-status</code>.</p><h3 id="why-does-domains-name-return-404" tabindex="-1">Why does /domains/:name return 404? <a class="header-anchor" href="#why-does-domains-name-return-404" aria-label="Permalink to &quot;Why does /domains/:name return 404?&quot;">​</a></h3><p>The name has never been registered. That&#39;s a normal response, not an error. Use <code>/availability?name=</code> for the three-state answer.</p><h3 id="does-resolution-check-whether-the-name-is-still-valid" tabindex="-1">Does resolution check whether the name is still valid? <a class="header-anchor" href="#does-resolution-check-whether-the-name-is-still-valid" aria-label="Permalink to &quot;Does resolution check whether the name is still valid?&quot;">​</a></h3><p>No. A resolver keeps returning the old address after expiry until it&#39;s overwritten. Check <code>nameExpires(tokenId) &gt; now</code> before acting on a resolution. Note <code>ownerOf</code> reverts past expiry, so it can&#39;t be used as a liveness probe without a try/catch.</p><h3 id="is-there-an-api-key-or-rate-limit" tabindex="-1">Is there an API key or rate limit? <a class="header-anchor" href="#is-there-an-api-key-or-rate-limit" aria-label="Permalink to &quot;Is there an API key or rate limit?&quot;">​</a></h3><p>No key. No limits enforced by the indexer itself, though a proxy or CDN in front may apply its own.</p><h2 id="transaction-errors" tabindex="-1">Transaction errors <a class="header-anchor" href="#transaction-errors" aria-label="Permalink to &quot;Transaction errors&quot;">​</a></h2><p>Every revert string you&#39;re likely to see, and what to do.</p><h3 id="registration-and-renewal" tabindex="-1">Registration and renewal <a class="header-anchor" href="#registration-and-renewal" aria-label="Permalink to &quot;Registration and renewal&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Revert</th><th>Meaning</th><th>Fix</th></tr></thead><tbody><tr><td><code>early</code></td><td>Registered before <code>minCommitAge</code> elapsed</td><td>Wait for the countdown</td></tr><tr><td><code>commit expired</code></td><td>More than <code>maxCommitAge</code> since the commit</td><td>Start over</td></tr><tr><td><code>committed</code></td><td>Same commitment hash submitted while one is live</td><td>Wait, or use a new secret</td></tr><tr><td><code>invalid</code></td><td>Name fails <code>valid()</code> — too short, uppercase, or a disabled 2-char name</td><td>Pick a valid name</td></tr><tr><td><code>duration</code></td><td>Outside 28 days – 100 years</td><td>Choose a duration in range</td></tr><tr><td><code>underpaid</code></td><td><code>msg.value</code> below the quote</td><td>Send at least <code>price()</code></td></tr><tr><td><code>owner</code></td><td>Owner is the zero address</td><td>Pass a real address</td></tr><tr><td><code>taken</code></td><td>Registered, or expired but in grace</td><td>Wait for the release date</td></tr><tr><td><code>short</code></td><td>Priced a name shorter than <code>minLen</code></td><td>—</td></tr><tr><td><code>2char</code></td><td>Two-char name while <code>price2</code> is zero</td><td>Tier is disabled</td></tr><tr><td><code>count</code></td><td><code>registerMany</code> with 0 or &gt;20 names</td><td>Batch up to 20</td></tr><tr><td><code>expired</code> (on <code>renew</code>)</td><td>Past expiry + 90 days</td><td>The name is released; register it normally</td></tr></tbody></table><h3 id="records" tabindex="-1">Records <a class="header-anchor" href="#records" aria-label="Permalink to &quot;Records&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Revert</th><th>Meaning</th><th>Fix</th></tr></thead><tbody><tr><td><code>!auth</code></td><td>Not the registry owner of the node</td><td>Call <code>reclaim</code> first</td></tr></tbody></table><h3 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Ownership&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Revert</th><th>Meaning</th><th>Fix</th></tr></thead><tbody><tr><td><code>expired</code> (on <code>ownerOf</code>)</td><td>Past expiry, including grace</td><td>Use <code>nameExpires</code> instead</td></tr><tr><td><code>none</code></td><td>Token was never minted</td><td>—</td></tr></tbody></table><h3 id="marketplace-1" tabindex="-1">Marketplace <a class="header-anchor" href="#marketplace-1" aria-label="Permalink to &quot;Marketplace&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Revert</th><th>Meaning</th><th>Fix</th></tr></thead><tbody><tr><td><code>price</code></td><td>Listing price is zero</td><td>Use <code>unlist</code> to withdraw instead</td></tr><tr><td><code>!owner</code></td><td>You don&#39;t own the token</td><td>—</td></tr><tr><td><code>!approved</code></td><td>Market not approved for the token</td><td><code>approve</code> first</td></tr><tr><td><code>!seller</code></td><td>You didn&#39;t create this listing</td><td>Only the lister can change it</td></tr><tr><td><code>!listed</code></td><td>Not listed, or already sold</td><td>—</td></tr><tr><td><code>price moved</code></td><td>Listing costs more than your <code>maxPrice</code></td><td>Re-quote and retry</td></tr><tr><td><code>seller changed</code></td><td>Seller transferred the name after listing</td><td>Stale listing</td></tr><tr><td><code>usdc listing</code></td><td>Listing settles in ERC-20 USDC</td><td>Use the USDC path</td></tr><tr><td><code>exceeds fee</code></td><td>Referral rates exceed <code>feeBps</code></td><td>Owner-side config</td></tr></tbody></table><h3 id="protocol-level" tabindex="-1">Protocol-level <a class="header-anchor" href="#protocol-level" aria-label="Permalink to &quot;Protocol-level&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Revert</th><th>Meaning</th></tr></thead><tbody><tr><td><code>!live</code></td><td>The registrar no longer controls the <code>.arc</code> node. Nothing you can fix.</td></tr><tr><td><code>!controller</code></td><td>Called a controller-only function directly. Go through the controller.</td></tr><tr><td><code>usdc off</code></td><td>ERC-20 USDC path not configured.</td></tr><tr><td><code>usdc pull</code></td><td>ERC-20 <code>transferFrom</code> failed. Check your allowance.</td></tr><tr><td><code>reentrant</code></td><td>Reentrancy guard tripped.</td></tr></tbody></table><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="can-t-reach-the-arc-network-right-now" tabindex="-1">&quot;Can&#39;t reach the Arc network right now.&quot; <a class="header-anchor" href="#can-t-reach-the-arc-network-right-now" aria-label="Permalink to &quot;&quot;Can&#39;t reach the Arc network right now.&quot;&quot;">​</a></h3><p>The app can&#39;t talk to its RPC endpoint. Press <strong>Try again</strong>. If it persists, the endpoint is down or misconfigured — most often CORS. See <a href="/docs/guide/connecting-a-wallet.html#rpc-endpoints">Connecting a wallet</a>.</p><h3 id="search-shows-nothing-at-all" tabindex="-1">Search shows nothing at all. <a class="header-anchor" href="#search-shows-nothing-at-all" aria-label="Permalink to &quot;Search shows nothing at all.&quot;">​</a></h3><p>Same cause. A failed lookup shows an error card with a retry button.</p><h3 id="data-may-be-out-of-date" tabindex="-1">&quot;Data may be out of date.&quot; <a class="header-anchor" href="#data-may-be-out-of-date" aria-label="Permalink to &quot;&quot;Data may be out of date.&quot;&quot;">​</a></h3><p>The indexer is behind the chain. On-chain reads are still correct; listings and activity may lag.</p><h3 id="every-balance-looks-wrong-by-a-huge-factor" tabindex="-1">Every balance looks wrong by a huge factor. <a class="header-anchor" href="#every-balance-looks-wrong-by-a-huge-factor" aria-label="Permalink to &quot;Every balance looks wrong by a huge factor.&quot;">​</a></h3><p>Currency decimals. The native token has <strong>18</strong>, not 6. Check your wallet&#39;s network configuration.</p><h3 id="my-wallet-is-on-the-wrong-network" tabindex="-1">My wallet is on the wrong network. <a class="header-anchor" href="#my-wallet-is-on-the-wrong-network" aria-label="Permalink to &quot;My wallet is on the wrong network.&quot;">​</a></h3><p>Use the switch button in the app&#39;s banner. Arc Testnet is chain ID <code>5042002</code>.</p><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><p>Check <a href="/docs/safety.html">Safety</a> if you think something malicious happened, and <a href="/docs/protocol/contracts.html">Contract addresses</a> to verify you&#39;re interacting with the real contracts.</p><p>Nobody legitimate will ever ask for your seed phrase.</p>',124)])])}const u=a(n,[["render",i]]);export{p as __pageData,u as default};
